-- Material- und Beschaffungsmodul. Additiv nach supabase/schema.sql ausfuehren.

create table if not exists public.material_items (
  id bigint generated by default as identity primary key,
  title text not null,
  procurement_source text not null check (procurement_source in ('lmu','lvr','privat')),
  category text not null check (category in ('dokumentation','fundverwaltung','feinwerkzeug','grobwerkzeug','wasser','it_foto','psa_erste_hilfe','infrastruktur','transport_lagerung','verbrauch','sonstiges')),
  target_quantity numeric(10,2),
  current_quantity numeric(10,2),
  unit text,
  status text not null default 'offen' check (status in ('offen','angefragt','zugesagt','beschafft','teilweise','fehlt','entfaellt')),
  priority text not null default 'mittel' check (priority in ('hoch','mittel','niedrig')),
  needed_by date,
  storage_location text,
  responsible_role text,
  note text,
  source_note text,
  archived_at timestamptz,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists material_items_source_idx on public.material_items(procurement_source);
create index if not exists material_items_category_idx on public.material_items(category);
create index if not exists material_items_status_idx on public.material_items(status);
create index if not exists material_items_archived_idx on public.material_items(archived_at);

drop trigger if exists touch_material_items_updated_at on public.material_items;
create trigger touch_material_items_updated_at before update on public.material_items for each row execute function public.touch_updated_at();

alter table public.material_items enable row level security;

drop policy if exists "material_items_select_active" on public.material_items;
create policy "material_items_select_active" on public.material_items for select to authenticated using (public.current_user_is_active());

drop policy if exists "material_items_insert_manager" on public.material_items;
create policy "material_items_insert_manager" on public.material_items for insert to authenticated with check (public.current_user_can_manage());

drop policy if exists "material_items_update_manager" on public.material_items;
create policy "material_items_update_manager" on public.material_items for update to authenticated using (public.current_user_can_manage()) with check (public.current_user_can_manage());

grant select, insert, update on public.material_items to authenticated;
grant usage, select on all sequences in schema public to authenticated;

on conflict do nothing;
